when.condition:
@{
          var filter = System.Net.WebUtility.UrlDecode(context.Request.Url.Query.GetValueOrDefault("$filter", ""));
          return !Regex.IsMatch(filter, @"^\s*scene_id eq '[A-Z]-\d{4}'(\s+and\s+.+)?\s*$")
              || Regex.IsMatch(filter, @"\bor\b", RegexOptions.IgnoreCase);
        }
